interface Shape {
    public double area();

    public double volume();
}

public class Circle implements Shape {
    @Override
    public double volume() {
        throw new UnsupportedOperationException("The volume cannot be calculated");
    }
}

public class Square implements Shape {
    @Override
    public double volume() {
        throw new UnsupportedOperationException("The volume cannot be calculated");
    }
}

